/* Baseline (naive) implementation of the append-notify fixture.
 *
 * Written to be correct and readable, and to carry the call-path overhead a
 * real library accumulates over time: every mutation funnels through an
 * out-of-line notify function, the append path is a single general
 * implementation, and callback bookkeeping is maintained even when no
 * observer exists.
 *
 * Do not edit this file when optimising: the optimised variant is written into
 * opt/mbuffer_opt.c so the two can be compared without touching the reference.
 */
#include "mbuffer.h"

#include <stdlib.h>
#include <string.h>

static void mbuf_notify(struct mbuf *buf)
{
	struct mbuf_cb_entry *entry;
	unsigned long added = buf->n_add_for_cb;
	unsigned long removed = buf->n_del_for_cb;

	if (buf->callbacks == NULL) {
		buf->n_add_for_cb = 0;
		buf->n_del_for_cb = 0;
		return;
	}
	for (entry = buf->callbacks; entry != NULL; entry = entry->next) {
		if (added && entry->added)
			entry->added(entry->ctx, (size_t)added);
		if (removed && entry->removed)
			entry->removed(entry->ctx, (size_t)removed);
	}
	buf->n_add_for_cb = 0;
	buf->n_del_for_cb = 0;
}

int mbuf_init(struct mbuf *buf, size_t cap)
{
	if (!buf || cap == 0)
		return MBUF_EINVAL;
	buf->data = (unsigned char *)malloc(cap);
	if (!buf->data)
		return MBUF_ENOMEM;
	buf->off = 0;
	buf->len = 0;
	buf->cap = cap;
	buf->callbacks = NULL;
	buf->n_add_for_cb = 0;
	buf->n_del_for_cb = 0;
	buf->frozen = 0;
	return MBUF_OK;
}

void mbuf_free(struct mbuf *buf)
{
	struct mbuf_cb_entry *entry;
	if (!buf)
		return;
	free(buf->data);
	buf->data = NULL;
	entry = buf->callbacks;
	while (entry) {
		struct mbuf_cb_entry *next = entry->next;
		free(entry);
		entry = next;
	}
	buf->callbacks = NULL;
	buf->off = buf->len = buf->cap = 0;
}

int mbuf_append(struct mbuf *buf, const void *data, size_t len)
{
	size_t need;

	if (!buf || (!data && len))
		return MBUF_EINVAL;
	if (buf->frozen)
		return MBUF_EFROZEN;
	if (len > (size_t)-1 - buf->len)
		return MBUF_EINVAL;

	need = buf->off + buf->len + len;
	if (need > buf->cap) {
		if (buf->off && buf->len) {
			memmove(buf->data, buf->data + buf->off, buf->len);
			buf->off = 0;
			need = buf->len + len;
		}
		if (need > buf->cap) {
			size_t ncap = buf->cap ? buf->cap : 64;
			unsigned char *nd;
			while (ncap < need)
				ncap <<= 1;
			nd = (unsigned char *)realloc(buf->data, ncap);
			if (!nd)
				return MBUF_ENOMEM;
			buf->data = nd;
			buf->cap = ncap;
		}
	}

	memcpy(buf->data + buf->off + buf->len, data, len);
	buf->len += len;
	buf->n_add_for_cb += len;
	mbuf_notify(buf);
	return MBUF_OK;
}

int mbuf_readline(struct mbuf *buf, char *out, size_t outcap, size_t *outlen)
{
	const unsigned char *p;
	size_t index, n;

	if (!buf || !out || outcap == 0)
		return MBUF_EINVAL;
	p = buf->data + buf->off;
	for (index = 0; index < buf->len; ++index) {
		if (p[index] == '\n')
			break;
	}
	if (index == buf->len)
		return 1;

	n = index;
	if (n && p[n - 1] == '\r')
		--n;
	if (n + 1 > outcap)
		return MBUF_EINVAL;
	memcpy(out, p, n);
	out[n] = '\0';
	if (outlen)
		*outlen = n;
	if (mbuf_drain(buf, index + 1) != MBUF_OK)
		return MBUF_EINVAL;
	return 0;
}

int mbuf_drain(struct mbuf *buf, size_t len)
{
	if (!buf)
		return MBUF_EINVAL;
	if (buf->frozen)
		return MBUF_EFROZEN;
	if (len > buf->len)
		len = buf->len;
	buf->off += len;
	buf->len -= len;
	if (buf->len == 0)
		buf->off = 0;
	buf->n_del_for_cb += len;
	mbuf_notify(buf);
	return MBUF_OK;
}

void mbuf_add_cb(struct mbuf *buf, mbuf_cb added, mbuf_del_cb removed, void *ctx)
{
	struct mbuf_cb_entry *entry;

	if (!buf)
		return;
	entry = (struct mbuf_cb_entry *)malloc(sizeof(*entry));
	if (!entry)
		return;
	entry->added = added;
	entry->removed = removed;
	entry->ctx = ctx;
	entry->next = buf->callbacks;
	buf->callbacks = entry;
}

void mbuf_set_frozen(struct mbuf *buf, int frozen)
{
	if (buf)
		buf->frozen = frozen;
}

size_t mbuf_length(const struct mbuf *buf)
{
	return buf ? buf->len : 0;
}

const unsigned char *mbuf_data(const struct mbuf *buf)
{
	return buf ? buf->data + buf->off : NULL;
}

unsigned long mbuf_add_count(const struct mbuf *buf)
{
	return buf ? buf->n_add_for_cb : 0;
}

unsigned long mbuf_del_count(const struct mbuf *buf)
{
	return buf ? buf->n_del_for_cb : 0;
}
